// Change these values only in a private copy after completing setup.
const cfg = {
  live: false,
  spreadsheetId: '',
  whatsappEnabled: false,
  graphVersion: '',
  phoneNumberId: '',
  ownerPhone: '',
  templateName: '', // Approved template with three body variables, or blank for free-form text.
  templateLanguage: 'en_US',
};
if (!cfg.live) throw new Error('Live access is disabled. Run the offline tests or configure a private staging copy.');
if (!/^[\w-]{15,}$/.test(cfg.spreadsheetId)) throw new Error('Configure the spreadsheet ID.');
if (cfg.whatsappEnabled && (!/^v\d+\.\d+$/.test(cfg.graphVersion) ||
    !/^\d+$/.test(cfg.phoneNumberId) || !/^[1-9]\d{6,14}$/.test(cfg.ownerPhone))) {
  throw new Error('Configure the Graph version, phone number ID and international owner number (digits only).');
}
return [{json: {...cfg, today: $now.setZone('Asia/Amman').toISODate()}}];

const headers = ['quote_id','customer_name','customer_email','amount','follow_up_date','status','draft_id','alert_status','error_message','draft_guard','alert_attempts','wa_message_id'];
const values = $json.values;
if (!Array.isArray(values) || !headers.every((h,i) => values[0]?.[i] === h)) {
  throw new Error('Quotes!A1:L1 must match the documented headers in order.');
}
const cfg = $('Configuration').first().json;
const rows = values.slice(1).map((cells,i) => ({
  row: i+2, ...Object.fromEntries(headers.map((h,j) => [h, String(cells[j] ?? '').trim()]))
})).filter(r => headers.some(h => r[h]));
const counts = new Map();
for (const r of rows) {
  const key = r.quote_id.toLowerCase();
  counts.set(key, (counts.get(key) || 0) + 1);
}
return rows.map(r => {
  const id = r.quote_id;
  const status = r.status.toLowerCase();
  const alert = r.alert_status.toLowerCase();
  let action = 'done', outcome = 'skipped', reason = '';
  if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,79}$/.test(id)) reason = 'Missing or unsupported quote ID';
  else if (counts.get(id.toLowerCase()) > 1) reason = 'Duplicate quote ID';
  else if (['closed','cancelled','canceled','accepted','rejected','sent','won','lost'].includes(status)) { /* terminal */ }
  else if (!['pending','draft created'].includes(status)) reason = 'Unknown quote status';
  else if (status === 'draft created' && !r.draft_id) reason = 'Draft Created without a draft ID';
  else if (status === 'pending' && r.draft_id) reason = 'Pending with a recorded draft ID';
  else if (status === 'draft created') {
    if (['sent','accepted'].includes(alert) || !cfg.whatsappEnabled) { /* complete or paused */ }
    else if (!['queued','retry'].includes(alert)) reason = (['auth blocked','sending','review'].includes(alert) && r.error_message) || 'Review alert history before authorizing Retry';
    else if (!/^([0-2])$/.test(r.alert_attempts || '0')) reason = 'Review alert attempt count';
    else if (r.wa_message_id) reason = 'Provider ID already present; verify before retry';
    else action = 'claimAlert';
  } else if (alert || r.wa_message_id || r.alert_attempts && r.alert_attempts !== '0') reason = 'Unexpected alert state on pending quote';
  else if (r.draft_guard && r.draft_guard !== 'Reserved') reason = 'Unknown draft guard';
  else if (!r.customer_name || !/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(r.customer_email)) reason = 'Invalid customer name or email';
  else {
    const date = r.follow_up_date;
    const instant = new Date(date + 'T00:00:00Z');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(+instant) || instant.toISOString().slice(0,10) !== date) reason = 'Invalid ISO calendar date';
    else if (date <= cfg.today || r.draft_guard === 'Reserved') action = 'search';
  }
  if (reason) {
    outcome = 'review';
    if (reason !== r.error_message) action = 'write';
  }
  return {json: {...r, action, outcome, reason, patch: reason ? {error_message:reason} : {},
    after:'done', subject:'Follow-up on Quotation QFUP-' + id}, pairedItem:{item:0}};
});

const rows = $input.all().map(i => i.json);
const issues = rows.filter(r => ['failure','review','retry'].includes(r.outcome));
if (issues.length) throw new Error(issues.length + ' row(s) need attention. ' + issues.slice(0,20).map(r => 'row ' + r.row + ' — ' + r.reason).join(' | '));
return [{json:{total:rows.length, processed:rows.filter(r => r.outcome === 'processed').length, skipped:rows.filter(r => r.outcome === 'skipped').length}}];

const s = {...$json};
if (s.action === 'claimAlert') {
  s.patch = {alert_status:'Sending', alert_attempts:String(Number(s.alert_attempts || 0)+1), error_message:''};
  s.action = 'write';
  s.after = 'notify';
}
if (s.action === 'write') {
  const cols = {status:'F',draft_id:'G',alert_status:'H',error_message:'I',draft_guard:'J',alert_attempts:'K',wa_message_id:'L'};
  s.writeBody = {valueInputOption:'RAW', data:Object.entries(s.patch).map(([k,v]) => {
    if (!cols[k]) throw new Error('Unsupported field');
    return {range:'Quotes!' + cols[k] + s.row, values:[[v]]};
  })};
}
if (s.action === 'create') {
  const body = 'Dear ' + s.customer_name + ',\n\nI am following up on our quotation ' + s.quote_id +
    '. Please let us know if you have any questions or would like us to adjust the quotation.\n\nBest regards,\nSales Team';
  const mime = ['To: ' + s.customer_email,'Subject: ' + s.subject,'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64','',
    Buffer.from(body,'utf8').toString('base64').match(/.{1,76}/g).join('\r\n')].join('\r\n');
  s.createBody = {message:{raw:Buffer.from(mime).toString('base64url')}};
}
if (s.action === 'notify') {
  const cfg = $('Configuration').first().json;
  const args = [s.quote_id, s.customer_name || 'Customer', s.amount || 'Unspecified'];
  s.notifyBody = {messaging_product:'whatsapp', to:cfg.ownerPhone};
  if (cfg.templateName) {
    Object.assign(s.notifyBody,{type:'template',template:{name:cfg.templateName, language:{code:cfg.templateLanguage},
      components:[{type:'body',parameters:args.map(text => ({type:'text',text}))}]}});
  } else {
    Object.assign(s.notifyBody,{type:'text',text:{body:'Quotation follow-up draft ready. Quote: ' + args[0] +
      '\nCustomer: ' + args[1] + '\nAmount: ' + args[2]}});
  }
}
return {json:s};

const s = {...$('Dispatch').item.json};
const {statusCode, body} = $json;
const ok = statusCode >= 200 && statusCode < 300;
const cfg = $('Configuration').first().json;
function finish(outcome, reason='') { Object.assign(s,{action:'done',outcome,reason}); }
function write(patch, after='done', outcome='processed') {
  Object.assign(s,{action:'write', patch, after, outcome, reason:patch.error_message || ''});
}
function review(reason) { write({error_message:reason},'done','review'); }
function record(id) {
  write({status:'Draft Created',draft_id:id,draft_guard:'',alert_status:'Queued',error_message:''},
    cfg.whatsappEnabled ? 'claimAlert' : 'done');
}
switch (s.action) {
  case 'write':
    if (!ok || body?.totalUpdatedCells !== Object.keys(s.patch).length) finish('failure','Sheet write unconfirmed; inspect row and start a fresh run');
    else { Object.assign(s,s.patch); s.action = s.after; }
    break;
  case 'search': {
    if (!ok || !body || typeof body !== 'object' || Array.isArray(body) ||
        (body.drafts !== undefined && !Array.isArray(body.drafts))) { review('Gmail search failed; retry on next run'); break; }
    const candidates = body.drafts || [];
    if (body.nextPageToken || candidates.length > 1) review('Multiple draft candidates; reconcile manually');
    else if (candidates.length === 1 && candidates[0]?.id) { s.candidate = candidates[0].id; s.action = 'inspect'; }
    else if (candidates.length) review('Invalid Gmail draft reference');
    else if (s.draft_guard) review('Reserved draft missing; check mailbox and execution before clearing guard');
    else write({draft_guard:'Reserved',error_message:''},'create');
    break;
  }
  case 'inspect': {
    const headers = body?.message?.payload?.headers || [];
    const vals = name => headers.filter(h => h.name.toLowerCase() === name).map(h => h.value.trim());
    const to = vals('to'), subj = vals('subject');
    const addr = to[0]?.match(/^[^<>,;]*<([^<>,;]+)>$/)?.[1] || to[0];
    if (ok && body.id === s.candidate && subj.length === 1 && subj[0] === s.subject && to.length === 1 &&
        addr?.toLowerCase() === s.customer_email.toLowerCase() && !vals('cc').length && !vals('bcc').length) record(body.id);
    else review('Draft ownership unverified; check exact subject and recipient');
    break;
  }
  case 'create':
    if (ok && typeof body?.id === 'string' && body.id) record(body.id);
    else review('Draft creation unconfirmed; reservation retained');
    break;
  case 'notify': {
    const code = Number(body?.error?.code);
    const mid = body?.messages?.[0]?.id;
    if (ok && typeof mid === 'string' && mid) write({alert_status:'Accepted',wa_message_id:mid,error_message:''});
    else {
      let state = 'Review', msg = 'Delivery outcome uncertain; reconcile before retry';
      if (code === 190 || statusCode === 401) { state = 'Auth Blocked'; msg = 'Replace or renew the private WhatsApp credential; then reset to Retry'; }
      else if ((statusCode === 429 || [130429,131056,4,80007].includes(code)) && Number(s.alert_attempts)<3) {
        state = 'Retry'; msg = 'Rate limited; retry on a subsequent daily run';
      } else if (code && statusCode >= 400 && statusCode < 500) msg = 'WhatsApp rejected request; review Meta code ' + code;
      write({alert_status:state,error_message:msg},'done',state === 'Retry' ? 'retry' : 'review');
    }
    break;
  }
  default: throw new Error('Unexpected response');
}
delete s.notifyBody;
delete s.createBody;
delete s.writeBody;
return {json:s};
